pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        Recorder rec = new Recorder();
        address[] memory tos = new address[](1);
        tos[0] = to;
        c.transfer(from, address(rec), tos, v);
        assertTrue(rec.lastFrom() == from);
    }
}

contract Recorder {
    address public lastFrom;
    function transferFrom(address from, address /*to*/, uint256 /*amount*/) external returns (bool) {
        lastFrom = from;
        return true;
    }
    fallback() external payable { revert(); }
}
